def row_to_record(row: dict[str, str], unknown_label: str) -> Record:
    """Convert a raw row from System C to a Record."""
    try:
        txn_date_str = row["txn_date"].strip()
        parsed = datetime.strptime(txn_date_str, "%d/%m/%Y")
        txn_date = parsed.date()
    except (ValueError, KeyError) as exc:
        raise LedgerParseError(
            f"System C txn_date {row.get('txn_date')!r} is not a valid dd/mm/yyyy date"
        ) from exc

    try:
        amount = Decimal(row["gross_amount"].strip())
    except (ValueError, KeyError) as exc:
        raise LedgerParseError(f"System C gross_amount {row.get('gross_amount')!r} is not a valid decimal") from exc

    code = row["ledger_acct"].strip().upper()
    return Record(
        record_id=row["ref"].strip(),
        source_system="C",
        date=txn_date,
        account_code=code,
        account_name=account_name(code, unknown_label),
        description=row["narrative"].strip(),
        amount=amount,
    )"}]

